def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    last_opp = history[-1][1]
    if last_opp == 'C':
        return 'C'
    consecutive = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consecutive += 1
        else:
            break
    if consecutive >= 3:
        if rng.random() < 0.1:
            return 'C'
    elif consecutive == 2:
        if rng.random() < 0.2:
            return 'C'
    return 'D'
